module.exports = JSON.parse("{\"0\":{\"buttons\":[{\"name\":\"Дай посмотреть.\",\"type\":\"perform\"},{\"name\":\"Пойду-ка я лучше...\"}],\"text\":\"Привет! Меня зовут Иван. Я могу помочь тебе с мебелью в твоем доме. С моей помощью ты можешь либо приобрести мебель за доллары, либо скрафтить за ресурсы. Интересно?\",\"sound\":\"cloud/npc/furniture/furniture.ogg\"}}");

